CREATE TABLE model_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES tasks ON DELETE SET NULL, step_id uuid REFERENCES task_steps ON DELETE SET NULL, profile_id text NOT NULL, capability text NOT NULL, attempt integer NOT NULL DEFAULT 0, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, cost_usd numeric(18,8) NOT NULL DEFAULT 0, latency_ms integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX model_usage_task_idx ON model_usage(task_id, created_at DESC);
CREATE TABLE task_checkpoints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES tasks ON DELETE CASCADE, step_id uuid REFERENCES task_steps ON DELETE CASCADE, state jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,step_id));
CREATE TABLE research_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES tasks ON DELETE CASCADE, step_id uuid REFERENCES task_steps ON DELETE CASCADE, url text NOT NULL, content_type text, size_bytes bigint, sha256 text NOT NULL, quarantine_path text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
